window.__POLYGON_SCRIPT_V2_PARTS__ = window.__POLYGON_SCRIPT_V2_PARTS__ || [];
window.__POLYGON_SCRIPT_V2_PARTS__.push("              <div class=\"compact-field\"><label>Патронов в запасе</label><input type=\"number\" min=\"0\" value=\"${unit.reserveAmmo}\" data-unit-detail-field=\"reserveAmmo\"></div>\n            </div><div class=\"unit-details-hint\">Полный состав дополнительных предметов и снаряжения пока не определён.</div></div></section>`;\n        }\n        return `\n          <section class=\"compact-section\"><div class=\"compact-section__head\"><span class=\"compact-section__title\">Начальное состояние</span></div><div class=\"compact-section__body\"><div class=\"unit-detail-grid unit-detail-grid--three\">\n            <div class=\"compact-field\"><label>Здоровье, %</label><input type=\"number\" min=\"0\" max=\"100\" value=\"${unit.health}\" data-unit-detail-field=\"health\"></div>\n            <div class=\"compact-field\"><label>Подавление, %</label><input type=\"number\" min=\"0\" max=\"100\" value=\"${unit.suppression}\" data-unit-detail-field=\"suppression\"></div>\n            <div class=\"compact-field\"><label>Усталость, %</label><input type=\"number\" min=\"0\" max=\"100\" value=\"${unit.fatigue}\" data-unit-detail-field=\"fatigue\"></div>\n            <div class=\"compact-field\"><label>Боевой дух, %</label><input type=\"number\" min=\"0\" max=\"100\" value=\"${unit.morale}\" data-unit-detail-field=\"morale\"></div>\n            <div class=\"compact-field\"><label>Предварительный осмотр, сек</label><input type=\"number\" min=\"0\" max=\"120\" value=\"${unit.awarenessSeconds}\" data-unit-detail-field=\"awarenessSeconds\"></div>\n            <div class=\"compact-field\"><label>Начальные ранения</label><select data-unit-detail-field=\"injuries\">${optionList(['Нет','Лёгкое','Среднее','Тяжёлое'], unit.injuries)}</select></div>\n          </div><div class=\"unit-details-hint\">Во время предварительного осмотра юнит воспринимает окружение и формирует память, но не двигается и не выполняет программу.</div></div></section>`;\n      }\n\n      function renderUnitDetailsModal() {\n        const unit = ensureUnitDefaults(selectedUnit());\n        if (!unit) { closeModal(); return; }\n        const tabs = [\n          ['basic','Основное'],\n          ['profiles','Профили'],\n          ['weapon','Вооружение'],\n          ['state','Начальное состояние']\n        ];\n        els.modal.className = 'modal modal--unit';\n        els.modal.innerHTML = `\n          <div class=\"modal__head\">\n            <div class=\"modal__title-wrap\"><div class=\"modal__kicker\">${escapeHtml(unit.sideLabel)} · ${escapeHtml(unit.archetype)}</div><div class=\"modal__title\" id=\"modalTitle\">${escapeHtml(unit.name)} — подробные настройки</div></div>\n            <button class=\"modal__close\" type=\"button\" data-unit-modal-action=\"cancel\" aria-label=\"Закрыть\">×</button>\n          </div>\n          <div class=\"modal__body\"><div class=\"unit-details-layout\">\n            <nav class=\"unit-details-nav\">${tabs.map(([key,label]) => `<button class=\"${state.unitDetailsTab === key ? 'is-active' : ''}\" type=\"button\" data-unit-details-tab=\"${key}\">${label}</button>`).join('')}</nav>\n            <div class=\"unit-details-main\">${unitDetailsBody(unit)}</div>\n          </div></div>\n          <div class=\"modal__footer\"><button class=\"danger-button\" type=\"button\" data-unit-action=\"delete\">Удалить</button><span style=\"flex:1\"></span><button class=\"ghost-button\" type=\"button\" data-unit-modal-action=\"cancel\">Отмена</button><button class=\"action-button\" type=\"button\" data-unit-modal-action=\"done\">Готово</button></div>`;\n      }\n\n      function renderFileModal() {\n        els.modal.className = 'modal modal--file';\n        els.modal.innerHTML = `\n          <div class=\"modal__head\">\n            <div class=\"modal__title-wrap\"><div class=\"modal__kicker\">Эксперимент</div><div class=\"modal__title\" id=\"modalTitle\">Файл</div></div>\n            <button class=\"modal__close\" type=\"button\" data-modal-close aria-label=\"Закрыть\">×</button>\n          </div>\n          <div class=\"modal__body\">\n            <div class=\"file-layout\">\n              <nav class=\"file-nav\">\n                <button class=\"is-active\" type=\"button\">Эксперимент</button>\n                <button type=\"button\" disabled>Настройки</button>\n              </nav>\n              <div class=\"file-main\">\n                <div class=\"field\"><label for=\"experimentName\">Название</label><input id=\"experimentName\" value=\"${escapeHtml(state.experiment.name)}\"></div>\n                <div class=\"field\" style=\"margin-top:10px\"><label for=\"experimentDescription\">Описание</label><textarea id=\"experimentDescription\">${escapeHtml(state.experiment.description)}</textarea></div>\n                <div class=\"file-actions\">\n                  <button class=\"ghost-button\" type=\"button\" data-file-action=\"new\">Новый эксперимент</button>\n                  <button class=\"ghost-button\" type=\"button\" data-file-action=\"open\">Открыть JSON</button>\n                  <button class=\"action-button\" type=\"button\" data-file-action=\"save\">Сохранить JSON</button>\n                  <button class=\"ghost-button\" type=\"button\" data-file-action=\"apply-meta\">Применить название</button>\n                </div>\n                <div class=\"prototype-note\">Окончательный состав и схема JSON ещё не определены. В прототипе сохраняются только демонстрационные данные интерфейса.</div>\n              </div>\n            </div>\n          </div>\n          <div class=\"modal__footer\"><button class=\"ghost-button\" type=\"button\" data-modal-close>Закрыть</button></div>`;\n      }\n\n      function renderEditorsModal() {\n        els.modal.className = 'modal';\n        els.modal.innerHTML = `\n          <div class=\"modal__head\">\n            <div class=\"modal__title-wrap\"><div class=\"modal__kicker\">Общие игровые данные</div><div class=\"modal__title\" id=\"modalTitle\">Редакторы</div></div>\n            <button class=\"modal__close\" type=\"button\" data-modal-close aria-label=\"Закрыть\">×</button>\n          </div>\n          <div class=\"modal__body\">\n            <div class=\"editors-layout\">\n              <nav class=\"editor-list\">${editorNames.map(name => `<button class=\"${state.activeEditor === name ? 'is-active' : ''}\" type=\"button\" data-editor-name=\"${escapeHtml(name)}\">${escapeHtml(name)}</button>`).join('')}</nav>\n              <section class=\"editor-workspace\">\n                <div class=\"editor-workspace__head\"><span class=\"editor-workspace__title\" id=\"activeEditorTitle\">${escapeHtml(state.activeEditor)}</span></div>\n                <div class=\"editor-workspace__body\">\n                  <div class=\"empty-state\">\n                    <div><div class=\"empty-state__icon\">▦</div><strong>${escapeHtml(state.activeEditor)}</strong><p>Содержимое редактора пока оставлено пустым. Все редакторы будут работать в этом едином окне.</p></div>\n                  </div>\n                </div>\n              </section>\n            </div>\n          </div>\n          <div class=\"modal__footer\"><button class=\"ghost-button\" type=\"button\" data-modal-close>Закрыть</button></div>`;\n      }\n\n      function updateEditorSelection(name) {\n        if (!editorNames.includes(name)) return;\n        state.activeEditor = name;\n        renderEditorsModal();\n      }\n\n      function applyFileMetadata() {\n        const nameInput = document.getElementById('experimentName');\n        const descInput = document.getElementById('experimentDescription');\n        state.experiment.name = nameInput?.value.trim() || 'Без названия';\n        state.experiment.description = descInput?.value || '';\n        els.experimentCaption.textContent = state.experiment.name;\n        toast('Название эксперимента применено');\n      }\n\n      function exportJson() {\n        applyFileMetadata();\n        const payload = {\n          format: 'real-wargame-polygon-prototype-v0',\n          prototype: true,\n          experiment: {\n            name: state.experiment.name,\n            description: state.experiment.description,\n            markers: state.experiment.markers,\n            units: state.units\n          }\n        };\n        const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });\n        const url = URL.createObjectURL(blob);\n        const link = document.createElement('a');\n        link.href = url;\n        link.download = `${state.experiment.name.replace(/[^a-zа-яё0-9_-]+/gi, '_') || 'experiment'}.json`;\n        document.body.append(link);\n        link.click();\n        link.remove();\n        URL.revokeObjectURL(url);\n        toast('Прототипный JSON сохранён');\n      }\n\n      function importJson(file) {\n        const reader = new FileReader();\n        reader.onload = () => {\n          try {\n            const data = JSON.parse(String(reader.result));\n            if (!data || typeof data !== 'object' || !data.experiment) throw new Error('Некорректная структура');\n            state.experiment.name = String(data.experiment.name || 'Без названия');\n            state.experiment.description = String(data.experiment.description || '');\n            state.experiment.markers = Array.isArray(data.experiment.markers) ? data.experiment.markers : [];\n            if (Array.isArray(data.experiment.units)) state.units = data.experiment.units;\n            state.selectedUnitId = null;\n            els.experimentCaption.textContent = state.experiment.name;\n            renderMarkers();\n            renderUnits();\n            renderInspector();\n            renderWorkspace();\n            renderFileModal();\n            toast('JSON открыт');\n          } catch (error) {\n            toast(`Не удалось открыть JSON: ${error.message}`);\n          }\n        };\n        reader.readAsText(file);\n      }\n\n      function toggleDropdown(button, dropdown) {\n        const opening = !dropdown.classList.contains('is-open');\n        closeDropdowns();\n        if (opening) {\n          dropdown.classList.add('is-open');\n          button.setAttribute('aria-expanded', 'true');\n        }\n");
